import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse('{"title":"Home, projects and empty project","description":"","frontmatter":{},"headers":[],"relativePath":"records/home-project-episode.md","filePath":"records/home-project-episode.md"}'),s={name:"records/home-project-episode.md"};function i(n,e,d,c,h,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<div class="warning custom-block"><p class="custom-block-title">Historical record</p><p>This page records what happened on a date, with its observed failures and limits. It is not a requirement for the current implementation. Current behaviour is in <a href="/Rho/docs/reference/status">Status</a>.</p></div><h1 id="home-projects-and-empty-project" tabindex="-1">Home, projects and empty project <a class="header-anchor" href="#home-projects-and-empty-project" aria-label="Permalink to &quot;Home, projects and empty project&quot;">​</a></h1><p>Updated 2026-10-27.</p><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p>The user supplied three reference screens (home with recent projects, the new-project sheet over a blurred page, an empty project page) and asked to optimize Rho&#39;s home, projects and empty-project screens against what the application actually does. The reference supplied layout weight and hierarchy, not values to copy: Rho has projects, workspaces, results, runs and Agents, and no project kinds, descriptions or import action.</p><p>The questions this pass answered:</p><ol><li>Does the projects list say something true and useful about each project instead of printing its absolute path?</li><li>Can a person with no projects, or a project with no work, see what to do next without reading a paragraph?</li><li>Does the page show where it is without repeating itself three times?</li></ol><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Disposable services with a debug Core binary and real Chrome (<code>/Applications/Google Chrome.app</code>, headless) at 1440, 1024, 768 and 390 CSS px. The native folder window was replaced at its own boundary (<code>NativeFolderPicker.prototype.choose</code>), the same way <code>ui-acceptance</code> does, so the create-project flow ran through the real UI. Scripts and screenshots live under <code>work/ui-review-20261027/</code> (ignored by Git):</p><ul><li><code>capture.mjs</code> — three projects, the sheet and an empty project page.</li><li><code>capture-created.mjs</code> — a project created through the sheet from a source folder holding CSV/R files.</li><li><code>capture-populated.mjs</code> — question, workspace with three views, a registered table and the Files page.</li><li><code>check-interactions.mjs</code> — the six checks listed under Verification.</li></ul><h2 id="observed-before" tabindex="-1">Observed before <a class="header-anchor" href="#observed-before" aria-label="Permalink to &quot;Observed before&quot;">​</a></h2><ul><li>Every project row printed the absolute path (<code>/private/tmp/rho-ui-fXpCCu/…</code>), including the service folder nobody needs to see.</li><li>Home named the same list three times over (a sidebar switcher saying &quot;Your projects&quot;, a topbar saying &quot;Projects&quot; and the page heading &quot;Your projects&quot;) and carried a subtitle that added nothing.</li><li>A created project&#39;s header said &quot;1 source folder&quot; without saying which folder.</li><li>An empty project showed a large &quot;Results&quot; card with three lines of explanation, a &quot;Recent activity&quot; column reading &quot;No runs yet.&quot;, and a shortcuts list that repeated the sidebar.</li><li>The create-project sheet had no close control, no reason next to the disabled primary button, and a heavy unblurred backdrop.</li></ul><h2 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h2><p><code>web/home.tsx</code>, <code>web/overview.tsx</code>, <code>web/project.tsx</code>, <code>web/main.tsx</code>, <code>web/theme.css</code>:</p><ul><li><strong>Home</strong> — one heading, one primary action, a search field and one list card. Each row carries a project-coloured symbol, the name, the folder the work lives in (source folders counted when there are several, home as <code>~</code>, only the last segments shown, <code>…/</code> when shortened, the exact path in the tooltip) and when it was last opened. With no projects, a centred empty state with the two real starting actions.</li><li><strong>Create project</strong> — a close control, the chosen folders as rows with their own paths, &quot;No folder chosen&quot; while empty, and one line naming what is missing before the primary button can be used. The page behind is dimmed and blurred.</li><li><strong>Project page</strong> — a header that names the project and the folder its work comes from. A project with nothing recorded opens a centred empty state with &quot;Work with Agent&quot; and &quot;Browse files&quot; instead of empty sections; which of the two leads is decided by the listing repair below. The activity column appears only when there are runs to report; the shortcuts that repeated the sidebar are gone.</li><li><strong>Shell</strong> — the topbar names the way back (<code>Projects / project / workspace</code>, collapsing to the current place below 768 px) and the sidebar keeps Project settings and Plugins together at its foot.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ul><li><code>npm run build</code> passed and Rho&#39;s 182 unit checks passed.</li><li><code>npm run acceptance:frontend</code> passed all 11 checks; screenshots in <code>work/ui-review-20261027/frontend/</code>.</li><li><code>npm run acceptance:pages</code> passed at four widths, with no overflow and no unnamed buttons on the new home, overview, settings and plugin screens.</li><li><code>npm run acceptance:shell</code> and <code>npm run acceptance:person</code> passed.</li><li><code>check-interactions.mjs</code> passed six checks: abbreviated locations with exact paths in tooltips, an emptied search that can be cleared, &quot;Open a project…&quot; landing focus on the first row, the sheet starting on its name field and returning focus to New project on Escape, a new project leading with its two next steps and no empty activity column, and the breadcrumb naming the project beside its section before returning to the list.</li><li><code>place-check.mjs</code> exercised the location line over nine path shapes — home directories, <code>/private/tmp</code> siblings, deep roots, a root directly under <code>/</code>, and 1 and 2 source folders — after a first version printed a bare <code>~</code> for a folder one level below the home directory and the project&#39;s own name for a root folder.</li><li>No browser page errors in any run.</li></ul><p>These checks show that the paths work and that the screens read as intended to me. They are not evidence that another person can follow them, and the visual judgments are mine.</p><h2 id="the-listing-defect-and-its-repair" tabindex="-1">The listing defect and its repair <a class="header-anchor" href="#the-listing-defect-and-its-repair" aria-label="Permalink to &quot;The listing defect and its repair&quot;">​</a></h2><p>The first pass recorded that a project made from source folders could not list them: <code>project.entries</code> read the project&#39;s own directory, which for those projects is an internal workspace folder, so a person who created a project from a folder of CSV files saw &quot;This folder is empty.&quot; The user asked for that capability defect to be fixed, so this pass changed the owner rather than the screens.</p><ul><li><strong>Listing.</strong> <code>project.entries</code> now lists the project&#39;s own directory together with one <code>@&lt;sourceId&gt;</code> folder entry per source folder, and descends into them under the same reference the file and document owners already resolve. A source that moved or disappeared is reported as <code>scope</code> instead of followed to whatever is there now; a folder that is not part of the project is refused. Nothing is unioned, copied or linked into the workspace directory. The method and capability descriptions now say this, and <code>project.openFile</code> names the reference it accepts.</li><li><strong>The second defect this uncovered.</strong> Opening a folder from this machine had been refused as <code>unauthorized</code> after the person had chosen it: <code>State.openSelected</code> demanded <code>Date.parse(expiresAt) &gt; Date.now()</code>, while this machine&#39;s own access carries no expiry — the rule <code>liveBrowser</code> and the request authenticator already use. <code>project.pick</code> is how &quot;Open folder…&quot; works, so the primary entry on Home was broken for the person at this machine and worked only in a narrowed link tab. The check was corrected to match the documented rule.</li><li><strong>Screens.</strong> The Files page names a source folder by its own name rather than its <code>@&lt;sourceId&gt;</code> alias, and descends and returns the same way. An empty project now reads its root once (one bounded listing) and leads with &quot;Browse files&quot; when that listing has anything in it, &quot;Work with Agent&quot; when it has nothing; a failed read keeps the Agent first rather than claiming an empty folder.</li></ul><h3 id="checks-for-the-repair" tabindex="-1">Checks for the repair <a class="header-anchor" href="#checks-for-the-repair" aria-label="Permalink to &quot;Checks for the repair&quot;">​</a></h3><ul><li>Rho 185/185 unit checks passed (182 before this pass). New tests cover: a project made from a source folder listing that folder, descending into it and its subfolders, opening a file from it by the reference <code>project.openFile</code> accepts, refusing an alias that is not part of the project and parent/absolute traversal, a moved or missing source being reported while the project still lists it, and this machine&#39;s own tab opening a folder with the native dialog and reading it. The last one fails on the previous commit and passes here.</li><li><code>acceptance:frontend</code>, <code>acceptance:pages</code>, <code>acceptance:shell</code> and <code>acceptance:person</code> passed.</li><li><code>work/ui-review-20261027/check-sources.mjs</code> in real Chrome: a project created from a folder of CSV/R files lists that folder in Files and leads with &quot;Browse files&quot;; the folder descends, nests into <code>scripts</code> and returns to the project root by its own name; a file inside it opens in the editor with its bytes; a project made from an empty folder still lists that folder; a folder opened directly with nothing in it leads with &quot;Work with Agent&quot;. Screenshots are in <code>work/ui-review-20261027/sources/</code>.</li></ul><h2 id="limits-and-next-questions" tabindex="-1">Limits and next questions <a class="header-anchor" href="#limits-and-next-questions" aria-label="Permalink to &quot;Limits and next questions&quot;">​</a></h2><ul><li>Listing a source folder still reads one level per call: a person who wants to know whether a project has <em>files</em> deeper inside must descend. The empty state therefore counts what the root lists (including the source folders), not every file.</li><li>A folder opened with &quot;Open folder…&quot; that is also a source folder of another project opens as its own project, because a chosen folder is a project. That is the existing identity rule, not a listing rule, and it can surprise.</li><li>Project colour is derived from the project identity and carries no meaning; it only helps the eye follow a project between the list and the sidebar.</li><li>Nothing here establishes dark mode, print, or a second person&#39;s reading of the three screens.</li></ul>',25)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
